CREATE INDEX oidc_transaction_previous ON oidc_transaction(previous_hash);
CREATE INDEX grant_compensation_proposal ON access_grant(org_id,compensation_proposal_id);
CREATE INDEX grant_compensation_event ON access_grant(org_id,compensation_event_id);
CREATE INDEX grant_compensation_term ON access_grant(org_id,compensation_term_id);

CREATE TABLE assessment_standing_policy(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,policy_revision INTEGER NOT NULL CHECK(policy_revision>0),service_subject_id TEXT NOT NULL,audience TEXT NOT NULL CHECK(audience IN('employee_followup','manager_followup')),expires_at INTEGER NOT NULL,provider_policy_id TEXT NOT NULL,template_version TEXT NOT NULL CHECK(template_version='periodic_structured_v1'),approved_by TEXT NOT NULL,approved_at INTEGER NOT NULL,PRIMARY KEY(org_id,employee_id,policy_revision),FOREIGN KEY(org_id,employee_id,policy_revision) REFERENCES interview_policy_version(org_id,employee_id,revision),FOREIGN KEY(org_id,service_subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,approved_by) REFERENCES subject(org_id,id),CHECK(service_subject_id<>approved_by)) STRICT;
CREATE TABLE assessment_source_epoch(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,epoch INTEGER NOT NULL CHECK(epoch>0),PRIMARY KEY(org_id,employee_id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id)) STRICT;
CREATE TABLE approved_assessment_input(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,window_id TEXT NOT NULL,generation_digest BLOB NOT NULL CHECK(length(generation_digest)=32),source_digest BLOB NOT NULL CHECK(length(source_digest)=32),facts_json TEXT NOT NULL CHECK(json_valid(facts_json) AND json_type(facts_json)='object'),requested_by TEXT NOT NULL,created_at INTEGER NOT NULL,approved_by TEXT,approved_at INTEGER,status TEXT NOT NULL CHECK(status IN('proposed','approved','invalidated','consumed')),CHECK((status='proposed' AND approved_by IS NULL AND approved_at IS NULL) OR (status IN('approved','consumed') AND approved_by IS NOT NULL AND approved_at IS NOT NULL) OR status='invalidated'),FOREIGN KEY(org_id,requested_by) REFERENCES subject(org_id,id),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,window_id) REFERENCES followup_window(org_id,id),FOREIGN KEY(org_id,approved_by) REFERENCES subject(org_id,id)) STRICT;
CREATE TABLE assessment_job(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,input_id TEXT NOT NULL,window_id TEXT NOT NULL,generation_digest BLOB NOT NULL CHECK(length(generation_digest)=32),source_digest BLOB NOT NULL CHECK(length(source_digest)=32),provider_policy_id TEXT NOT NULL,audience TEXT NOT NULL CHECK(audience IN('employee_followup','manager_followup')),state TEXT NOT NULL CHECK(state IN('queued','leased','completed','failed','cancelled')),attempt INTEGER NOT NULL DEFAULT 0 CHECK(attempt>=0),max_attempts INTEGER NOT NULL DEFAULT 3 CHECK(max_attempts BETWEEN 1 AND 10),fence INTEGER NOT NULL DEFAULT 0 CHECK(fence>=0),lease_owner TEXT,lease_token_hash BLOB CHECK(lease_token_hash IS NULL OR length(lease_token_hash)=32),lease_expires_at INTEGER,deadline_at INTEGER NOT NULL,created_at INTEGER NOT NULL,completed_at INTEGER,error_code TEXT,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,input_id) REFERENCES approved_assessment_input(org_id,id),FOREIGN KEY(org_id,window_id) REFERENCES followup_window(org_id,id),CHECK((state='leased' AND lease_owner IS NOT NULL AND lease_token_hash IS NOT NULL AND lease_expires_at IS NOT NULL) OR (state<>'leased' AND lease_owner IS NULL AND lease_token_hash IS NULL AND lease_expires_at IS NULL))) STRICT;
CREATE TABLE assessment_payload(org_id TEXT NOT NULL,id TEXT NOT NULL,employee_id TEXT NOT NULL,result_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),object_kind TEXT NOT NULL CHECK(object_kind='assessment_result'),purpose TEXT NOT NULL CHECK(purpose='interview'),schema_type TEXT NOT NULL CHECK(schema_type='assessment.result.v1'),schema_version INTEGER NOT NULL CHECK(schema_version=1),format_version INTEGER NOT NULL,algorithm TEXT NOT NULL,dek_id TEXT NOT NULL,kek_id TEXT NOT NULL,kek_version INTEGER NOT NULL,wrapped_dek BLOB NOT NULL,sealed_bytes BLOB NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,result_id,revision),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id)) STRICT;
CREATE TABLE assessment_result(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,job_id TEXT NOT NULL,current_revision INTEGER NOT NULL CHECK(current_revision>0),status TEXT NOT NULL CHECK(status IN('draft','published','discarded','invalidated')),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,job_id),FOREIGN KEY(org_id,job_id) REFERENCES assessment_job(org_id,id)) STRICT;
CREATE TABLE assessment_result_revision(org_id TEXT NOT NULL,result_id TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload_id TEXT NOT NULL,editor_subject_id TEXT,source_digest BLOB NOT NULL CHECK(length(source_digest)=32),status TEXT NOT NULL CHECK(status IN('draft','published')),created_at INTEGER NOT NULL,PRIMARY KEY(org_id,result_id,revision),FOREIGN KEY(org_id,result_id) REFERENCES assessment_result(org_id,id),FOREIGN KEY(org_id,payload_id) REFERENCES assessment_payload(org_id,id),FOREIGN KEY(org_id,editor_subject_id) REFERENCES subject(org_id,id)) STRICT;
CREATE TABLE assessment_job_receipt(org_id TEXT NOT NULL,worker_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-AI-05','OP-AI-06','OP-AI-07')),key TEXT NOT NULL,digest BLOB NOT NULL CHECK(length(digest)=32),job_id TEXT NOT NULL,result_id TEXT,recorded_at INTEGER NOT NULL,PRIMARY KEY(org_id,worker_id,operation,key),FOREIGN KEY(org_id,job_id) REFERENCES assessment_job(org_id,id),FOREIGN KEY(org_id,result_id) REFERENCES assessment_result(org_id,id)) STRICT;
CREATE UNIQUE INDEX approved_assessment_input_active_generation ON approved_assessment_input(org_id,window_id,generation_digest) WHERE status<>'invalidated';
CREATE UNIQUE INDEX assessment_job_active_generation ON assessment_job(org_id,window_id,generation_digest) WHERE state IN('queued','leased');
CREATE INDEX assessment_job_queue ON assessment_job(state,created_at,id);
CREATE INDEX assessment_job_employee ON assessment_job(org_id,employee_id,created_at,id);
CREATE INDEX assessment_result_employee ON assessment_result(org_id,employee_id,updated_at,id);
CREATE TRIGGER assessment_standing_policy_no_update BEFORE UPDATE ON assessment_standing_policy BEGIN SELECT RAISE(ABORT,'immutable assessment policy'); END;
CREATE TRIGGER assessment_standing_policy_no_delete BEFORE DELETE ON assessment_standing_policy BEGIN SELECT RAISE(ABORT,'immutable assessment policy'); END;
CREATE TRIGGER approved_assessment_input_owner BEFORE UPDATE ON approved_assessment_input WHEN NEW.org_id IS NOT OLD.org_id OR NEW.employee_id IS NOT OLD.employee_id OR NEW.id IS NOT OLD.id OR NEW.window_id IS NOT OLD.window_id OR NEW.generation_digest IS NOT OLD.generation_digest OR NEW.source_digest IS NOT OLD.source_digest OR NEW.facts_json IS NOT OLD.facts_json OR NEW.requested_by IS NOT OLD.requested_by OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'immutable assessment input'); END;
CREATE TRIGGER approved_assessment_input_transition BEFORE UPDATE ON approved_assessment_input WHEN NOT ((OLD.status='proposed' AND NEW.status IN('approved','invalidated')) OR (OLD.status='approved' AND NEW.status IN('consumed','invalidated')) OR (OLD.status='consumed' AND NEW.status='invalidated')) BEGIN SELECT RAISE(ABORT,'invalid assessment input transition'); END;
CREATE TRIGGER assessment_payload_immutable BEFORE UPDATE ON assessment_payload BEGIN SELECT RAISE(ABORT,'immutable assessment payload'); END;
CREATE TRIGGER assessment_payload_no_delete BEFORE DELETE ON assessment_payload BEGIN SELECT RAISE(ABORT,'immutable assessment payload'); END;
CREATE TRIGGER assessment_revision_immutable BEFORE UPDATE ON assessment_result_revision BEGIN SELECT RAISE(ABORT,'immutable assessment result revision'); END;
CREATE TRIGGER assessment_revision_no_delete BEFORE DELETE ON assessment_result_revision BEGIN SELECT RAISE(ABORT,'immutable assessment result revision'); END;
CREATE TRIGGER assessment_job_receipt_immutable BEFORE UPDATE ON assessment_job_receipt BEGIN SELECT RAISE(ABORT,'immutable assessment receipt'); END;
CREATE TRIGGER assessment_job_receipt_no_delete BEFORE DELETE ON assessment_job_receipt BEGIN SELECT RAISE(ABORT,'immutable assessment receipt'); END;
CREATE TRIGGER grant_invalidates_assessment AFTER UPDATE ON access_grant WHEN COALESCE(NEW.employee_id,NEW.object_employee_id) IS NOT NULL BEGIN UPDATE approved_assessment_input SET status='invalidated' WHERE org_id=NEW.org_id AND employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id) AND status IN('approved','consumed'); UPDATE assessment_job SET state='cancelled',lease_owner=NULL,lease_token_hash=NULL,lease_expires_at=NULL,error_code='authorization_changed' WHERE org_id=NEW.org_id AND employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id) AND state IN('queued','leased'); UPDATE assessment_result SET status='invalidated',updated_at=CAST(unixepoch('subsec')*1000000 AS INTEGER) WHERE org_id=NEW.org_id AND employee_id=COALESCE(NEW.employee_id,NEW.object_employee_id) AND status IN('draft','published'); END;
CREATE TRIGGER interview_invalidates_assessment AFTER UPDATE ON interview BEGIN UPDATE approved_assessment_input SET status='invalidated' WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND status IN('approved','consumed'); UPDATE assessment_job SET state='cancelled',lease_owner=NULL,lease_token_hash=NULL,lease_expires_at=NULL,error_code='source_changed' WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND state IN('queued','leased'); UPDATE assessment_result SET status='invalidated',updated_at=CAST(unixepoch('subsec')*1000000 AS INTEGER) WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND status IN('draft','published'); END;
CREATE TRIGGER interview_invalidates_assessment_insert AFTER INSERT ON interview BEGIN UPDATE approved_assessment_input SET status='invalidated' WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND status IN('approved','consumed'); UPDATE assessment_job SET state='cancelled',lease_owner=NULL,lease_token_hash=NULL,lease_expires_at=NULL,error_code='source_changed' WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND state IN('queued','leased'); UPDATE assessment_result SET status='invalidated',updated_at=CAST(unixepoch('subsec')*1000000 AS INTEGER) WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND status IN('draft','published'); END;
