CREATE TRIGGER action_invalidates_assessment_insert AFTER INSERT ON action_item BEGIN UPDATE approved_assessment_input SET status='invalidated' WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND status IN('approved','consumed'); UPDATE assessment_job SET state='cancelled',lease_owner=NULL,lease_token_hash=NULL,lease_expires_at=NULL,error_code='source_changed' WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND state IN('queued','leased'); UPDATE assessment_result SET status='invalidated',updated_at=CAST(unixepoch('subsec')*1000000 AS INTEGER) WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND status IN('draft','published'); END;
