CREATE TRIGGER action_invalidates_proposed_assessment AFTER UPDATE ON action_item BEGIN UPDATE approved_assessment_input SET status='invalidated' WHERE org_id=NEW.org_id AND employee_id=NEW.employee_id AND status='proposed'; END;
